#### Example 1: Extension Webpack Module Federation Config

_[To be completed]_

```javascript
// webpack.config.js for extension (remote)
const ModuleFederationPlugin = require('webpack/lib/container/ModuleFederationPlugin');

module.exports = {
  plugins: [
    new ModuleFederationPlugin({
      name: 'texasClaimsExtension',
      filename: 'remoteEntry.js',
      exposes: {
        './ClaimsValidator': './src/components/ClaimsValidator',
        './EligibilityWidget': './src/components/EligibilityWidget'
      },
      shared: {
        react: { singleton: true, requiredVersion: '^18.0.0' },
        'react-dom': { singleton: true, requiredVersion: '^18.0.0' },
        '@gainwell/design-system-react': { singleton: true }
      }
    })
  ]
};
```

