#### Example 3: Dynamic Remote Module Loading

_[To be completed]_

```typescript
// Dynamic loading of tenant-specific extension
import { loadRemoteModule } from '@gainwell/extensions-sdk-react';

async function loadTenantExtension(tenantId: string) {
  const remoteUrl = await getRemoteUrlForTenant(tenantId);

  const module = await loadRemoteModule({
    remoteUrl,
    scope: 'tenantExtension',
    module: './ClaimsValidator'
  });

  return module.default;
}
```

